    window.addEventListener('keydown', (e) => {
      const activeTag = document.activeElement ? document.activeElement.tagName.toLowerCase() : '';
      if (activeTag === 'input' || activeTag === 'textarea' || activeTag === 'select') return;

      if (e.key === 'p' || e.key === 'P') {
        e.preventDefault();
        toggleAutoSync();
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        fetchState(true);
      } else if (e.key >= '0' && e.key <= '9' && globalData && globalData.conversations) {
        const keys = Object.keys(globalData.conversations);
        const idx = e.key === '0' ? 9 : parseInt(e.key, 10) - 1;
        if (keys[idx]) {
          e.preventDefault();
          selectConvo(keys[idx]);
        }
      }
    });

    // Initialize and Auto-refresh every 3.5 seconds
    fetchState();
    setInterval(fetchState, 3500);"

