.nta-badge::before {
  content: "";
  position: absolute;
  top: -6px;
  left: -6px;
  right: -6px;
  bottom: -6px;
  min-width: 44px;
  min-height: 44px;
  pointer-events: auto;
}

/* Touch wrapper ensuring minimum 44x44px bounding box for touch targets */
.nta-badge-container,
.nta-badge-touch-target {
